import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const _=JSON.parse('{"title":"《般若波罗蜜多心经》白话直译","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/心经.md","filePath":"meditation/心经.md"}'),r={name:"meditation/心经.md"};function n(i,p,s,d,c,l){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="《般若波罗蜜多心经》白话直译" tabindex="-1">《般若波罗蜜多心经》白话直译 <a class="header-anchor" href="#《般若波罗蜜多心经》白话直译" aria-label="Permalink to &quot;《般若波罗蜜多心经》白话直译&quot;">​</a></h1><p>原文</p><p>观自在菩萨，行深般若波罗蜜多时，照见五蕴皆空，度一切苦厄。</p><p>舍利子，色不异空，空不异色，色即是空，空即是色，受想行识，亦复如是。</p><p>舍利子，是诸法空相，不生不灭，不垢不净，不增不减。</p><p>是故空中无色，无受想行识，无眼耳鼻舌身意，无色声香味触法，无眼界，乃至无意识界，无无明，亦无无明尽，乃至无老死，亦无老死尽。</p><p>无苦集灭道，无智亦无得。</p><p>以无所得故，菩提萨埵，依般若波罗蜜多故，心无挂碍。</p><p>无挂碍故，无有恐怖，远离颠倒梦想，究竟涅槃。</p><p>三世诸佛，依般若波罗蜜多故，得阿耨多罗三藐三菩提。</p><p>故知般若波罗蜜多，是大神咒，是大明咒，是无上咒，是无等等咒，能除一切苦，真实不虚</p><p>故说般若波罗蜜多咒，即说咒曰：</p><p>揭谛揭谛，波罗揭谛，波罗僧揭谛，菩提萨婆诃。</p><hr><p>般若波罗蜜多心经</p><p>（意为&quot;智慧到彼岸的精髓&quot;）</p><p>观世音菩萨在修习深奥的智慧时，看透了五种构成人的要素都是空无实体的，从而超越了一切痛苦。</p><p>舍利弗，物质与空性并无区别，空性也与物质并无区别，物质就是空性，空性就是物质。</p><p>感受、思想、行为、意识也是如此。</p><p>舍利弗，所有事物的本质是空性，既不产生也不消失，既不污秽也不清净，既不增加也不减少</p><p>因此在空性中没有物质，没有感受、思想、行为、意识，没有眼、耳、鼻、舌、身、意，没有色、声、香、味、触、法。</p><p>没有眼睛的领域，乃至没有意识的领域，没有无知，也没有无知的终结，乃至没有衰老和死亡，也没有衰老和死亡的终结。</p><p>没有苦、集、灭、道四圣谛，没有智慧也没有得到，因为没有什么可得到。</p><p>菩萨依靠智慧</p><p>心中没有障碍，因为没有障碍所以没有恐惧，远离错误的幻想，最终达到涅槃。</p><p>过去、现在、未来的所有佛，都是依靠智慧而获得无上正等正觉。</p><p>因此知道般若波罗蜜多是伟大的神咒，是伟大的明咒，是无上的咒语，是无与伦比的咒语，能消除一切痛苦，真实不虚，所以说般若波罗蜜多咒。</p><p>即刻说咒言：揭谛揭谛 波罗揭谛 波罗僧揭谛 菩提萨婆诃（咒语的意思是：去吧去吧，去到彼岸吧，大家一起去到彼岸吧，愿智慧圆满）。</p>',28)]))}const f=t(r,[["render",n]]);export{_ as __pageData,f as default};
